-- Athena saved query (Product_B2C_Intl)
-- ID: 72f74ae5-a92f-4ad0-929f-b96834804fc3
-- Name: RTC AC Sort SD Level Txns - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH srp AS ( SELECT mri_session_id, rb_user_id, MAX( CASE WHEN channel_exp_info IS NULL THEN 'null' WHEN contains(channel_exp_info,'COMFORT_SCORE_AB:V0') THEN 'V0' WHEN contains(channel_exp_info,'COMFORT_SCORE_AB:V1') THEN 'V1' WHEN contains(channel_exp_info,'COMFORT_SCORE_AB:V2') THEN 'V2' WHEN contains(channel_exp_info,'COMFORT_SCORE_AB:V3') THEN 'V3' WHEN contains(channel_exp_info,'COMFORT_SCORE_AB:V4') THEN 'V4' ELSE 'others' END ) AS exp_variant FROM user_interaction.search_route_details WHERE __time >= TIMESTAMP '2026-07-01 18:30:00' AND __time < TIMESTAMP '2026-07-13 18:30:00' AND os = 'Android' AND group_id > 0 AND country = 'IND' GROUP BY 1,2 ) SELECT -- t.source_location_id, -- t.destination_location_id, -- t.source_location, -- t.destination_location, t.operator_id, bo.bo_name AS rtc_name, -- CASE -- WHEN t.is_ac THEN 'AC' -- ELSE 'non-AC' -- END AS is_ac, COALESCE(s.exp_variant,'null') AS exp_variant, COUNT(DISTINCT t.tin) AS txn_count FROM transaction.bus_ticket_events t JOIN srp s ON t.mri_session_id = s.mri_session_id AND t.rb_user_id = s.rb_user_id JOIN lis.bo_mappings bo ON bo.vendor_id = t.operator_id AND bo.is_rtc = 'RTC' WHERE t.date_of_issue >= TIMESTAMP '2026-07-01 18:30:00' AND t.date_of_issue < TIMESTAMP '2026-07-13 18:30:00' AND t.sales_channel = 'RB:MOBILEWEB#droidapp' AND t.country_code = 'IND' AND t.event_class = 2 AND t.event_type = 101 AND t.tin IS NOT NULL AND t.tin NOT IN ('','null') GROUP BY 1,2,3 -- ,4 -- ,5,6,7 -- ,8 ORDER BY txn_count DESC;
